# nginx.conf -- the simplest reverse-proxy load balancer: one front door, two
# backends. nginx terminates the client connection and forwards to a backend.
events {}

http {
    upstream app {
        server web1:80;        # backend 1
        server web2:80;        # backend 2 (round-robin across them by default)
    }

    server {
        listen 80;             # the single address clients talk to

        location / {
            proxy_pass http://app;             # forward to the upstream group
            proxy_set_header Host $host;       # preserve the original Host header
        }
    }
}

# nginx.conf -- balancing policies. Round-robin is the DEFAULT; uncomment ONE
# alternative. Weights and a backup server are shown on the server lines.
events {}

http {
    upstream app {
        # Uncomment ONE policy. NOTE: ip_hash and hash do NOT allow a 'backup' server.
        # least_conn;                     # send to the backend with fewest active conns
        # ip_hash;                        # sticky by client IP (simple session affinity)
        # hash $request_uri consistent;   # consistent hashing by URL (cache-friendly)

        server web1:80 weight=3;          # weighted: web1 gets ~3x the share
        server web2:80 weight=1;          # (a 'backup' server works only with round-robin/least_conn)
    }

    server {
        listen 80;
        location / { proxy_pass http://app; }
    }
}

# nginx.conf -- resilience with OSS NGINX: PASSIVE health checks plus timeouts and
# fail-over. (ACTIVE health checks via the `health_check` directive require NGINX
# Plus or a third-party module; OSS ejects a backend only after real failures.)
events {}

http {
    upstream app {
        server web1:80 max_fails=3 fail_timeout=30s;   # eject after 3 fails for 30s
        server web2:80 max_fails=3 fail_timeout=30s;
    }

    server {
        listen 80;
        location / {
            proxy_pass http://app;
            proxy_connect_timeout 2s;                  # cap time to connect
            proxy_read_timeout 5s;                     # cap time to first/next byte
            proxy_next_upstream error timeout http_502 http_503;  # retry the next backend
            proxy_next_upstream_tries 2;               # bound total retries
        }
    }
}

# nginx.conf -- a complete reverse-proxy load balancer. Mount it at
# /etc/nginx/nginx.conf and run the official nginx image on the same Docker
# network as the backends (web1, web2). `events {}` is mandatory at the top level.
events {
    worker_connections 1024;
}

http {
    upstream backend {
        least_conn;                                 # fewest active connections wins
        server web1:80 max_fails=3 fail_timeout=30s;
        server web2:80 max_fails=3 fail_timeout=30s;
    }

    server {
        listen 80;
        server_name _;

        location / {
            proxy_pass http://backend;
            proxy_set_header Host $host;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            proxy_set_header X-Forwarded-Proto $scheme;
            proxy_connect_timeout 2s;
            proxy_read_timeout 5s;
            proxy_next_upstream error timeout http_502 http_503;
        }

        location /healthz {
            return 200 "ok\n";                      # the LB's own liveness endpoint
        }
    }
}
